import { useState } from "react";
export default function Tppp(){
    let [Id,SetId]=useState("");
    let [Des,SetDes]=useState("");
    let [Price,SetPrice]=useState("");
    let [Total,SetTotal]=useState("");
    let [List,SetList]=useState("")
    let f1=(event)=>{SetId(event.target.value)}
    let f2=(event)=>{SetDes(event.target.value)}
    let f3=(event)=>{SetPrice(event.target.value)}
    const AddToList=()=>{
        SetList([...List,Id,Des,Price])
        SetId=("");
        SetDes=("");
        SetPrice=("")
    }
    const Calculat=()=>{
        const sum=List.reduce((acc,val)=>acc+val,0)
        SetTotal(sum)
    }
    return(
        <div>
            <form>
                <label>ID</label>
                <input type="text" value={Id}onChange={f1}></input>
                <label>Disignation</label>
                <input type="text" value={Des}onChange={f2}></input>
                <label>prix</label>
                <input type="text"value={Price} onChange={f3}></input>
                <button type="button" onClick={AddToList} >ajouter</button>
                <ul>
                    {List.map((item,index)=>(
                        <li key={index}>{index.Id}-{index.Des}-{index.Price}</li>
                    ))}
                </ul>
                
                <button type="button" onClick={Calculat}></button>
            </form>
        </div>
        
    )
}
